import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"间隙锁与谓词锁","description":"","frontmatter":{"title":"间隙锁与谓词锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gap-locks-predicate.md","filePath":"cs/gap-locks-predicate.md","lastUpdated":1789023840000}'),c={name:"cs/gap-locks-predicate.md"};function h(B,a,_,m,A,f){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="间隙锁与谓词锁" tabindex="-1">间隙锁与谓词锁 <a class="header-anchor" href="#间隙锁与谓词锁" aria-label="Permalink to &quot;间隙锁与谓词锁&quot;">​</a></h1><div class="epigraph"><p>幻象来自范围内新插入。谓词锁锁住「满足条件的未来行」；间隙/next-key 用索引空隙近似。</p><footer>—— 据 Eswaran et al. 谓词锁；InnoDB next-key；主干幻读课的锁实现</footer></div><p><a href="/cs/intention-locks">上一课</a>把锁挂在层次上。本课不画 IX 矩阵。缺口是幻读：主干已定义；2PL 行锁锁不住「还不存在的行」。谓词锁（predicate lock）在理论上锁 \\(\\sigma_\\theta\\)；工程用索引间隙锁、next-key 锁近似。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>SELECT … WHERE id BETWEEN 10 AND 20</code> 可重复读下，另一事务插入 id=15 会幻。谓词锁：对 \\(\\theta\\) 加锁，插入者检查新行是否满足任何活跃谓词。实现难：谓词任意、相交判定贵。间隙锁：在 B+ 叶上锁 (10,20) 之间的间隙，插入必须过间隙锁。next-key：间隙+记录，避免幻与丢失更新的组合缝。</p><p>无索引：可能退回表级锁。这是计划与并发的耦合——没有合适索引，可串行更贵。</p><p><span class="marginnote">Eswaran, Gray, Lorie, Traiger，CACM 1976 事务一致与谓词。InnoDB REPEATABLE READ 实际用 next-key，与标准 RR 不完全同。本课机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扫描带索引条件则对碰到的间隙加锁（隔离级别够高时）。插入：定位叶，检查间隙冲突。哈希索引无序，间隙难定义，幻象保护弱或表锁。OCC/SSI 用读范围记录代替间隙锁。</p><p>死锁：间隙锁与行锁互相等待，wait-for 要包含它们。</p>',10)),(e(),s(E,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RNG%5B%22%E8%8C%83%E5%9B%B4%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20GAP%5B%22%E9%94%81%E4%BD%8F%E5%8F%B6%E4%B8%8A%E9%97%B4%E9%9A%99%22%5D%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%22%5D%20--%3E%20CHK%5B%22%E8%BF%87%E9%97%B4%E9%9A%99%E9%94%81%22%5D%0A%20%20PRED%5B%22%E4%BB%BB%E6%84%8F%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20TBL%5B%22%E6%88%96%E8%A1%A8%E9%94%81%20%2F%20%E7%9C%9F%E8%B0%93%E8%AF%8D%E9%94%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>性能：范围越大锁越多，并发下降。这是「可串行的税」。覆盖扫描仍要锁间隙，不只盖列。分区：间隙在分区内，跨分区插入要各间隙或更粗锁。</p><p>与 MVCC：快照读可避免部分幻，写偏斜与插入幻仍要 SSI 或间隙。Postgres RR 用快照，serializable 用 SSI，间隙模型与 InnoDB 不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画 wait-for 算法。也不把间隙当空间 R 树锁。谓词完全一般不可判定相交，工程必近似。</p><p>后课默认：防幻要锁范围或记谓词；无索引则粗锁。wait-for 图：检测锁等待环。</p><p>间隙是索引序上的谓词近似，不是 SQL 谓词的完备实现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>谓词锁理论防幻；间隙/next-key 用 B+ 空隙实现。</li><li>无序索引与无索引使保护退化。</li><li>wait-for 图下一课：死锁检测。</li><li>出处：Eswaran et al. 1976；InnoDB next-key；Gray and Reuter。</li></ul>',9))])}const D=i(c,[["render",h]]);export{u as __pageData,D as default};
